static volatile int   g_rtdIdLo = 0, g_rtdIdHi = 0;   // hi <= lo = whole rig
// ---- 30.72: the crossbow's OTHER half ------------------------------------
// "c6 x30 moves one part of the crossbow, the other part stays put." A count
// of 4 at c6 is not a bone set at all - it is a plain per-draw LocalToWorld
// for a STATIC mesh, which is how attachments like the crossbow's body are
// drawn. Those translations ARE world positions, so unlike bones they can be
// filtered by distance to the camera (c5) - the filter that was hopeless for
// rig-local bone data is exactly right here. Diagnostic first: log what sits
// near the camera, then drive it in the next build once the space is known.
// ---- 30.74: FIND THE RIG'S WORLD MATRIX ----------------------------------
// The probe proved the bone constants are COMPONENT space: they hold the pose,
// not the placement. Something else maps that component into the world, and
// for a skinned draw UE3 has to upload it as a constant too - we have simply
// never looked for it. That matrix is the lever this feature actually needs:
// write it and the rig lands where we say in WORLD space, with no camera in
// the path at all, so head coupling becomes structurally impossible instead of
// something to cancel.
// Instrument: keep a ring of the most recent small uploads, and when an arms
// upload goes by, flush the ring plus the calls that follow. The matrix set
// just before or just after the bones is the candidate.
struct VcEnt { UINT reg, count; float v[16]; };
static VcEnt          g_vcRing[48];
static int            g_vcRingN = 0;
static volatile LONG  g_vcArmed = 0;      // 1 = flush at the next arms upload
static volatile LONG  g_vcAfter = 0;      // calls still to log after the flush
static volatile bool  g_rtdProbeOn = false;
static double         g_rtdProbeUntil = 0.0, g_rtdProbeNext = 0.0;
static volatile LONG  g_rtdStaticLog = 0;
static float          g_rtdStaticRadius = 250.0f;

// ============================================================================
// 30.77 - VR HANDS: our own weapons, drawn in VR space.
//
// The render-time drive is finished. The deciding test - a pure yaw counter-
// rotation, controllers out of the loop, swept across every gain - never held
// the weapon still while the head physically turned. Arkane draws the view
// model in camera space with no world matrix anywhere in the constant map, and
// the renderer offers no seam to get between the arms and the camera.
//
// So stop asking the engine. Hide its arms (we cannot place them, but we
// certainly can collapse them) and draw our own geometry at the controller
// pose, in the eye render targets we already own. The engine is no longer in
// the loop, so tracking is 1:1 by construction and there is nothing to
// calibrate away.
//
// Vertices are transformed to clip space on the CPU using the same
// GetProjectionRaw composition the eye quads use, and triangles are sorted
// back-to-front, so this needs no constant buffers and no depth buffer.
// ============================================================================
struct HandVert { float pos[4]; float col[4]; float uv[2]; };
static ID3D11VertexShader* g_hmVS = NULL;
static ID3D11PixelShader*  g_hmPS = NULL;
static ID3D11InputLayout*  g_hmLayout = NULL;
static ID3D11Buffer*       g_hmVB = NULL;
static bool   g_hmReady = false;
static const char* kHandShaderSrc =
    "struct VSIn  { float4 pos : POSITION; float4 col : COLOR0; float2 uv : TEXCOORD0; };\n"
    "struct VSOut { float4 pos : SV_Position; float4 col : COLOR0; float2 uv : TEXCOORD0; };\n"
    "VSOut vsmain(VSIn i) { VSOut o; o.pos=i.pos; o.col=i.col; o.uv=i.uv; return o; }\n"
    "Texture2D  skin : register(t0);\n"
    "SamplerState samp : register(s0);\n"
    "float4 psmain(VSOut i) : SV_Target {\n"
    "    float4 t = skin.Sample(samp, i.uv);\n"
    "    if (t.a < 0.35) discard;\n"          // alpha-cut, for straps and belts
    "    return float4(t.rgb * i.col.rgb * 2.0, 1.0);\n"
    "}\n";

static bool   g_hmEnable = false;        // [VRHands] Enabled - OFF until the
                                         // engine-side path is properly ruled out
static bool   g_hmHideGame = true;       // collapse the game's own arms
static float  g_hmScale = 1.0f;
static float  g_hmPos[2][3] = { {0,0,0}, {0,0,0} };      // metres, extra per-hand nudge
static float  g_hmRot[2][3] = { {0,0,0}, {0,0,0} };      // deg: yaw, pitch, roll
// 0 none, 1 sword, 2 crossbow, 3 empty hand, 4 pistol, 5 grenade, 6 springrazor,
// 7 heart. Chosen automatically from the equipped weapon's MESH ASSET NAME -
// the same identification FpCollect already refreshes every 750 ms, so swapping
// weapons in game swaps the model in your hand.
enum { HM_NONE=0, HM_SWORD=1, HM_XBOW=2, HM_HAND=3, HM_PISTOL=4,
       HM_GRENADE=5, HM_RAZOR=6, HM_HEART=7, HM_COUNT=8 };
static int    g_hmModel[2] = { 2, 1 };
static bool   g_hmAuto = true;           // follow the equipped weapon
static volatile LONG g_hmRebuild = 0;    // model changed; rebuild on the render thread
// Per-MODEL hold offsets, not per-hand: a pistol and a sword want different
// angles in the same hand, and auto-switching would otherwise fight the trim.
static float  g_hmMRot[HM_COUNT][3];
static float  g_hmMPos[HM_COUNT][3];
// Every first-person rig we want gone, by upload size. The left-hand weapons
// have their own sizes (the user measured x30 crossbow, x6 gun, x3 grenades)
// so hiding only the arms and the sword left them floating. 0 ends the list.
static UINT   g_hmHideSize[12] = { 3, 6, 30, 36, 144, 0, 0, 0, 0, 0, 0, 0 };
// The crossbow's body is a STATIC mesh (c6 x4 = a plain LocalToWorld), so it
// has no bones to collapse - but its translation is a real world position, so
// it can be caught by distance from the camera. View models ride the camera
// and are always close; keep the radius small so real props are not culled.
static float  g_hmHideStaticUU = 70.0f;
static bool   g_hmHideStatic = true;
// 30.79: a plain distance test was far too blunt - a doorway you are standing
// in front of is well inside 110 uu, so the cull ate real world geometry (the
// invisible doors in Campbell's level). View-model statics are not merely
// close, they are drawn in the same cluster as the first-person rigs, right
// after them. So the cull only stays open for a few draws after a rig has been
// collapsed, which world geometry elsewhere in the frame can never enter.
static volatile LONG g_hmStaticWindow = 0;
static int    g_hmStaticDraws = 6;
// model geometry, built once in controller-local metres
struct HmTri { float p[3][3]; float c[4]; float uv[3][2]; int tex; };
#define HM_MAXTRI 6000
static HmTri* g_hmGeo[2] = { NULL, NULL };
static int    g_hmGeoN[2] = { 0, 0 };
