// ----------------------------------------------------------------------------
// Logging
// ----------------------------------------------------------------------------
static void Log(const char* fmt, ...)
{
    if (!g_log) return;
    EnterCriticalSection(&g_logLock);
    fprintf(g_log, "[%10lu] ", (unsigned long)GetTickCount());
    va_list ap; va_start(ap, fmt);
    vfprintf(g_log, fmt, ap);
    va_end(ap);
    fprintf(g_log, "\n");
    fflush(g_log);
    LeaveCriticalSection(&g_logLock);
}

