    g_sprintHoldCfg   = IniFloat(ini, "Input", "SprintHold", 0) != 0.0f;    // 38.28, off by default from 38.29
    g_sprintPulseMs   = IniFloat(ini, "Input", "SprintPulseMs", 130.0f);
